void opeu_hurricane_present(uint8_t ds[65536], HostEvent event) {
  uint16_t flag;
  if ((SCENARIO & 0x7f) == 3 && MONTH >= 7 && MONTH <= 9)
    flag = 1;
  else
    flag = 0;
  CUE15();
  CONTEXT(CURRENT);
  FORMAT3(TEXT, LOOKUP(0x6d), flag ? HURRICANE(0) : HURRICANE(1));
  MESSAGE(TEXT, PERSON);
}

/* Local names fix C 6.0a's frame slots (wet -2, ob -4, s -6, x -8, y -10,
 * n -12). */
void opeu_partisan_event(uint8_t ds[65536], HostEvent event) {
  uint16_t    wet;
  OBJECTIVE_P ob;
  uint8_t     s, x, y, n;
  if (WEATHER != 5)
    return;
  if ((SCENARIO & 0x7f) == 3 && MONTH >= 7 && MONTH <= 9)
    wet = 1;
  else
    wet = 0;
  SHOW_HURRICANE(0xe7, CURRENT);
  for (y = 0; y < 40; y++)
    for (x = 0; x < 40; x++) {
      if (MAP_CODE(x, y) != 10)
        continue;
      if (CELL_SIDE(x, y) != 0xff)
        continue;
      if (RANDOM(wet == 0 ? 100 : 70) != 8)
        continue;
      FORMAT3(TEXT, LOOKUP(0x1b), wet ? PARTISAN(0) : PARTISAN(1));
      for (s = 0; s < 2; s++) {
        MESSAGE(TEXT, SIDE_RECORD(s, 3));
        RISING(x, y, s);
      }
      MARK5(x, y);
      ERASE(x, y);
    }
  ob = FIRST_OBJECTIVE;
  for (n = 0; n < 21; NEXT_OBJECTIVE(ob), n++) {
    if (!USED(ob))
      continue;
    if (RANDOM(wet == 0 ? 80 : 50))
      continue;
    if (ELIGIBLE(ob) && STATUS(s = OBJ_SIDE(ob)) == 1) {
      FORMAT4(TEXT, LOOKUP(0x1c), wet ? PARTISAN(0) : PARTISAN(1), ob);
      MESSAGE(TEXT, SIDE_RECORD(s, 3));
      RISING(OBJ_X(ob), OBJ_Y(ob), s);
    }
    SUB_BYTE(RANDOM(10) + (wet == 0 ? 3 : 5), STRENGTH_P(ob));
  }
}

